import sys

MOD = 998244353
MAX_A = 100000


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    values = data[1:]

    spf = list(range(MAX_A + 1))
    for i in range(2, 317):
        if spf[i] == i:
            for j in range(i * i, MAX_A + 1, i):
                if spf[j] == j:
                    spf[j] = i

    phi = list(range(MAX_A + 1))
    for p in range(2, MAX_A + 1):
        if spf[p] == p:
            for j in range(p, MAX_A + 1, p):
                phi[j] -= phi[j] // p

    weighted_divisor_sums = [0] * (MAX_A + 1)
    result = 0
    weight = 1
    output = []

    for x in values:
        t = x
        divisors = [1]
        while t > 1:
            p = spf[t]
            exponent = 0
            while t % p == 0:
                t //= p
                exponent += 1
            old_divisors = divisors[:]
            multiplier = 1
            for _ in range(exponent):
                multiplier *= p
                divisors.extend(d * multiplier for d in old_divisors)

        contribution = sum(phi[d] * weighted_divisor_sums[d] for d in divisors) % MOD
        result = (2 * result + contribution) % MOD
        output.append(str(result))

        for d in divisors:
            weighted_divisor_sums[d] = (weighted_divisor_sums[d] + weight) % MOD
        weight = weight * 2 % MOD

    sys.stdout.write('\n'.join(output))


if __name__ == '__main__':
    main()

