    N, M, Q = map(int, input().split())
    edges = [None] * M
    for i in range(M):
        a, b, c = map(int, input().split())
        edges[i] = (a-1, b-1, c)
    queries = []
    closed = [False] * M
    for _ in range(Q):
        q = list(map(int, input().split()))
        if q[0] == 1:
            closed[q[1]-1] = True
        queries.append(q)

    INF = 10**30
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0
    for idx, (a, b, c) in enumerate(edges):
        if not closed[idx]:
            dist[a][b] = dist[b][a] = c

    for k in range(N):
        dk = dist[k]
        for i in range(N):
            dik = dist[i][k]
            if dik == INF:
                continue
            di = dist[i]
