import sys
from math import gcd

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[0], data[1]
    processes = []
    j = 2
    for _ in range(n):
        a, p, b, q = data[j:j + 4]
        j += 4
        processes.append((a, p, b, q, b // gcd(a, b)))

    def min_cost(k, a, p, b, q, period):
        if k == 0:
            return 0
        xmax = (k + a - 1) // a
        positive_bound = (k - 1) // a
        best = 10**30
        # For a fixed x modulo period, the cost is linear while the
        # required number of T machines is positive. Check the endpoints
        # of that range, and the boundary where it becomes zero.
        for r in range(min(period, xmax + 1)):
            last = r + ((xmax - r) // period) * period
            candidates = {r, last}
            if positive_bound >= r:
                candidates.add(r + ((positive_bound - r) // period) * period)
            for x_count in candidates:
                y_count = max(0, (k - a * x_count + b - 1) // b)
                total = p * x_count + q * y_count
                if total < best:
                    best = total
        return best

    def feasible(k):
        total = 0
        for a, p, b, q, period in processes:
            total += min_cost(k, a, p, b, q, period)
            if total > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

