class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)

        # depth[t] = operations needed for t to reach 1.
        depth = [0] * (m + 1)
        for t in range(2, m + 1):
            depth[t] = 1 + depth[t.bit_count()]
        good = [t for t in range(1, m + 1) if depth[t] <= k - 1]

        fact = [1] * (m + 1)
        for i in range(1, m + 1):
            fact[i] = fact[i - 1] * i % MOD
        invfact = [1] * (m + 1)
        invfact[m] = pow(fact[m], MOD - 2, MOD)
        for i in range(m, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        def choose(a, b):
            if b < 0 or b > a:
                return 0
            return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD

        ans = 0
        pref = 0
        for i, ch in enumerate(s):
            if ch == '1':
                remaining = m - i - 1
                # First differing bit is 0; complete with the required ones.
                for ones in good:
                    need = ones - pref
                    if 0 <= need <= remaining:
                        ans += choose(remaining, need)
                pref += 1
        return ans % MOD

