    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)
        # depth[t] is number of popcount operations needed for t to reach 1.
        depth = [0] * (m + 1)
        for t in range(2, m + 1):
            depth[t] = 1 + depth[t.bit_count()]
        good = [t for t in range(1, m + 1) if depth[t] <= k - 1]
        # Pascal row values C(a,b), needed for a <= m.
        C = [[0] * (m + 1) for _ in range(m + 1)]
        C[0][0] = 1
        for a in range(1, m + 1):
            C[a][0] = C[a][a] = 1
            for b in range(1, a):
                C[a][b] = (C[a - 1][b - 1] + C[a - 1][b]) % MOD
        ans = 0
        pref = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = m - i - 1
                for ones in good:
                    need = ones - pref
                    if 0 <= need <= rem:
                        ans += C[rem][need]
                pref += 1
        return ans % MOD

