def possible(people,l,r,n):
    p=list(range(n+1))
    def find(x):
        while p[x]!=x:
            p[x]=p[p[x]]; x=p[x]
        return x
    for s,t in people[l:r+1]:
        x=find(s); y=find(t)
        if x!=y: p[x]=y
    adj=[[] for _ in range(n+1)]
    indeg=[0]*(n+1)
    for s,t in people[l:r+1]:
        a,b=sorted((s,t)); root=find(a)
        if s<t:
            for v in range(a+1,b):
                x,y=root,find(v)
                if x==y:return False
                adj[x].append(y); indeg[y]+=1
        else:
            for v in range(a+1,b):
                x,y=find(v),root
                if x==y:return False
                adj[x].append(y); indeg[y]+=1
    roots=[i for i in range(1,n+1) if find(i)==i]
    q=deque(i for i in roots if indeg[i]==0)
    seen=0
    while q:
        x=q.popleft(); seen+=1
        for y in adj[x]:
            indeg[y]-=1
            if indeg[y]==0:q.append(y)
    return seen==len(roots)

