import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [0] * n
    k = 2
    for _ in range(m):
        u, v = data[k] - 1, data[k + 1] - 1
        k += 2
        adj[u] |= 1 << v
        adj[v] |= 1 << u

    # Reduce the adjacency matrix over GF(2) to reduced row-echelon form.
    rows = adj[:]
    pivots = []
    r = 0
    for c in range(n):
        q = next((i for i in range(r, n) if (rows[i] >> c) & 1), None)
        if q is None:
            continue
        rows[r], rows[q] = rows[q], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivots.append(c)
        r += 1

    pivot_set = set(pivots)
    basis = []
    for free in range(n):
        if free in pivot_set:
            continue
        x = 1 << free
        for row_index, pivot in enumerate(pivots):
            if (rows[row_index] >> free) & 1:
                x |= 1 << pivot
        basis.append(x)

    # A vertex can be nonzero in some kernel vector iff it occurs in a
    # nullspace basis vector. Give each basis vector its own integer bit.
    covered = 0
    for x in basis:
        covered |= x
    if covered != (1 << n) - 1:
        print("No")
        return

    values = [0] * n
    for bit, x in enumerate(basis):
        for vertex in range(n):
            if (x >> vertex) & 1:
                values[vertex] |= 1 << bit

    print("Yes")
    print(*values)

