from typing import List
from array import array

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]  # clockwise
        size = n * m
        straight = [[array('H', [0]) * size for _ in range(2)] for _ in range(4)]
        turned = [[array('H', [0]) * size for _ in range(2)] for _ in range(4)]

        # phase 0 means the current cell should be 2; phase 1 means 0.
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    idx = r * m + c
                    nr, nc = r + dr, c + dc
                    ni = nr * m + nc if 0 <= nr < n and 0 <= nc < m else -1
                    for p, value in enumerate((2, 0)):
                        if grid[r][c] == value:
                            straight[d][p][idx] = 1 + (straight[d][1-p][ni] if ni >= 0 else 0)

            # With a turn still available, either continue straight or turn now.
            clockwise = (d + 1) % 4
            tr, tc = dirs[clockwise]
            for r in rows:
                for c in cols:
                    if grid[r][c] not in (0, 2):
                        continue
                    idx = r * m + c
                    for p, value in enumerate((2, 0)):
                        if grid[r][c] != value:
                            continue
                        best = 0
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            best = turned[d][1-p][nr * m + nc]
                        nr, nc = r + tr, c + tc
                        if 0 <= nr < n and 0 <= nc < m:
                            best = max(best, straight[clockwise][1-p][nr * m + nc])
                        turned[d][p][idx] = 1 + best

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                answer = max(answer, 1)
                for d, (dr, dc) in enumerate(dirs):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        answer = max(answer, 1 + turned[d][0][nr * m + nc])
        return answer

