class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = (powers[i - 1] * 10) % k

        # Each half-digit contributes to the two mirrored positions,
        # except for the center digit of an odd-length palindrome.
        coeff = []
        for i in range(m):
            j = n - 1 - i
            if i == j:
                coeff.append(powers[i])
            else:
                coeff.append((powers[i] + powers[j]) % k)

        # can[i][r]: the positions i..m-1 can contribute residue r.
        can = [bytearray(k) for _ in range(m + 1)]
        can[m][0] = 1
        for i in range(m - 1, -1, -1):
            c = coeff[i]
            nxt, cur = can[i + 1], can[i]
            for r in range(k):
                for d in range(10):
                    if nxt[(r - d * c) % k]:
                        cur[r] = 1
                        break

        # Greedily fix each digit as large as possible while retaining
        # a feasible completion.
        half = []
        rem = 0
        for i, c in enumerate(coeff):
            minimum = 1 if i == 0 else 0
            for d in range(9, minimum - 1, -1):
                needed = (-rem - d * c) % k
                if can[i + 1][needed]:
                    half.append(str(d))
                    rem = (rem + d * c) % k
                    break

        left = ''.join(half)
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

