class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        cnt = Counter(s)
        freq = [cnt[chr(97+i)] for i in range(26)]
        ans = len(s)
        for target in range(1, max(freq) + 1):
            dp = {0: 0}  # amount passed from the previous letter
            for i, c in enumerate(freq):
                nd = {}
                for incoming, cost in dp.items():
                    for final in (0, target):
                        # Either keep all remaining characters here, or pass the
                        # surplus on to the next letter.
                        outs = (0,) if i == 25 else (0, max(0, c + incoming - final))
                        for outgoing in set(outs):
                            value = cost + outgoing + abs(c + incoming - outgoing - final)
                            if value < nd.get(outgoing, 10**9):
                                nd[outgoing] = value
                dp = nd
            ans = min(ans, min(dp.values()))
        return ans

